import json, os, re
D = os.environ["INPUT_DIR"]
plan = json.load(open(os.path.join(D, "ogretim_plani.json"), encoding="utf-8"))
prog = json.load(open(os.path.join(D, "ders_programi.json"), encoding="utf-8"))
tr = json.load(open(os.path.join(D, "transkript.json"), encoding="utf-8"))

def walk(o, path=""):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from walk(v, f"{path}.{k}")
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from walk(v, f"{path}[{i}]")
    else:
        yield path, o

# 1) Algoritma Analizi kayitlari (tum dosyalar)
print("=== Algoritma kayitlari ===")
for name, data in [("plan", plan), ("program", prog), ("transkript", tr)]:
    for p, v in walk(data):
        if isinstance(v, str) and "lgoritma" in v:
            print(name, p, "=>", v)

# Ders kayitlarini bul
def find_records(data, key_pred):
    out = []
    def rec(o):
        if isinstance(o, dict):
            if key_pred(o): out.append(o)
            for v in o.values(): rec(v)
        elif isinstance(o, list):
            for v in o: rec(v)
    rec(data)
    return out

algo_plan = find_records(plan, lambda o: "ad" in o and "lgoritma Analizi" in str(o.get("ad", "")))
algo_prog = find_records(prog, lambda o: "lgoritma Analizi" in str(o.get("ders", "")) )
algo_tr = find_records(tr, lambda o: "lgoritma Analizi" in str(o.get("ad", "")))
print("\nPlan kaydi:", json.dumps(algo_plan, ensure_ascii=False, indent=1))
print("\nProgram kaydi:", json.dumps(algo_prog, ensure_ascii=False, indent=1))
print("\nTranskript kaydi:", json.dumps(algo_tr, ensure_ascii=False, indent=1))

# 2) GNO yeniden hesap
KAT = {"AA":4.0,"BA":3.5,"BB":3.0,"CB":2.5,"CC":2.0,"DC":1.5,"DD":1.0,"FD":0.5,"FF":0.0}
print("\n=== Transkript dersleri ===")
rows = tr["dersler"]
print("kayit sayisi:", len(rows))
print("ornek anahtarlar:", sorted(set(k for r in rows for k in r.keys())))
akts_sum = 0; puan_sum = 0; gecen = 0
for r in rows:
    n = r.get("not")
    if n in KAT:
        a = r.get("akts", 0)
        akts_sum += a
        puan_sum += a * KAT[n]
print("harf notlu toplam AKTS:", akts_sum, "agirlikli ortalama:", round(puan_sum/akts_sum, 4) if akts_sum else None)
print("obs_ozet:", tr.get("obs_ozet"))
print("notlar:", sorted(set(str(r.get("not")) for r in rows)))
