import json, os, datetime
from collections import defaultdict
IN = os.environ["INPUT_DIR"]
def load(n):
    with open(os.path.join(IN, n), encoding="utf-8") as f: return json.load(f)
def norm(s):
    return str(s or "").replace("İ", "i").replace("I", "ı").lower().strip()
def m(x):
    h, mi = x.strip().split(":"); return int(h)*60+int(mi)
def aralik(s):
    a, b = s.split("-"); return m(a), m(b)

prog = load("ders_programi.json"); trs = load("transkript.json")
dersler = prog["dersler"]

# 1) İşletim Sistemleri I B şubesi
ois = [d for d in dersler if norm(d["ders"]) == "işletim sistemleri ı"]
print("İşletim Sistemleri I kayıtları (sube, gun, saatler):")
for d in ois: print("  ", d["sube"], d["gun"], d["saatler"], d["derslik"])
b_kayitlar = [d for d in ois if d["sube"] == "B"]
print("\nSONUÇ-1: İşletim Sistemleri I B şubesi ->", b_kayitlar[0]["gun"], b_kayitlar[0]["saatler"], "| derslik:", b_kayitlar[0]["derslik"])
print("Bu kayıtta yuva/sinif:", b_kayitlar[0]["yuva"], b_kayitlar[0]["sinif"])

# 2) Bu dönem (2026 Güz) transkript dersleri
bu = [t for t in trs["dersler"] if t["yil"] == 2026 and t["donem"] == "Güz"]
print("\nBu dönem transkript dersleri (not henüz yok):", [(t["kod"], t["ad"]) for t in bu])

# 3) Ders programındaki tüm şubeleri kod bazında topla
kod_kayit = defaultdict(list)
for d in dersler: kod_kayit[d["kod"]].append(d)

# 4) Her ders için her şube ile B şubesi çakışma kontrolü
b = b_kayitlar[0]
print("\nÇakışma kontrolü (B şubesi ile her şube/ders karşılaştırması):")
sonuc = []
for t in bu:
    if t["kod"] == b["kod"]:  # kendisi
        continue
    for d in kod_kayit.get(t["kod"], []):
        if d["gun"] != b["gun"]: continue
        for s1 in b["saatler"]:
            for s2 in d["saatler"] or []:
                a1,e1 = aralik(s1); a2,e2 = aralik(s2)
                if a1 < e2 and a2 < e1:
                    sonuc.append((t["ad"], d["sube"], d["gun"], s1, s2))
if sonuc:
    for r in sonuc: print("  ÇAKIŞMA:", r)
else:
    print("  Çakışma bulunamadı (gün eşleşmesi ve saat aralıkları üzerinden).")

# 5) Gün bazında tüm şube/derslerle ilişkisi (bilgi): Salı'da B şubesi ile aynı saatte olanlar
print("\nB şubesiyle aynı gün (", b["gun"], ") programda olan TÜM dersler (kod ve şube):")
for d in dersler:
    if d["gun"] != b["gun"] or d["kod"] == b["kod"]: continue
    ovl = []
    for s1 in b["saatler"]:
        for s2 in d["saatler"] or []:
            a1,e1 = aralik(s1); a2,e2 = aralik(s2)
            if a1 < e2 and a2 < e1: ovl.append(s2)
    if ovl: print(f"   {d['ders']} {d['sube']} ({d['kod']}) -> {sorted(set(ovl))}")

print("\nTatil kontrolü:")
for t in prog["tatiller"]:
    dt = datetime.date.fromisoformat(t["tarih"])
    print("  ", t["tarih"], dt.strftime("%A"), t.get("baslangic",""), t["aciklama"])
